window.RP_SESSION={"id":"S-f66ff4cc4c4d","messages":[{"id":"RP-II-0112283","time":"2026-06-30T15:06:00+09:00","room":"RP II","name":"아도니스","profile":"올리브","identity":"reviewed","type":"dialogue","body":"안뇽 나 아도니스.","characters":["P-6eeed2b4661f"]},{"id":"RP-II-0112284","time":"2026-06-30T15:07:00+09:00","room":"RP II","name":"아도니스","profile":"올리브","identity":"reviewed","type":"dialogue","body":" 책을 읽기 위해, 그루터기의 흙을 살짝 털어주자. 이미 죽은 나무니 양해를 구할 필요도 없겠지.","characters":["P-6eeed2b4661f"]},{"id":"RP-II-0112285","time":"2026-06-30T15:08:00+09:00","room":"RP II","name":"아도니스","profile":"올리브","identity":"reviewed","type":"dialogue","body":" 옛날 옛날 아주 먼 옛날에 잭과 질 남매가 살았습니다. 둘은 가난하지만 행복했어요.","characters":["P-6eeed2b4661f"]},{"id":"RP-II-0112286","time":"2026-06-30T15:08:00+09:00","room":"RP II","name":"아도니스","profile":"올리브","identity":"reviewed","type":"dialogue","body":"행복하다니 잘 됐다.","characters":["P-6eeed2b4661f"]},{"id":"RP-II-0112287","time":"2026-06-30T15:09:00+09:00","room":"RP II","name":"아도니스","profile":"올리브","identity":"reviewed","type":"dialogue","body":"그러던 어느 날, 아이들의 아버지가 말했어요. `오늘은 나무를 베러 멀리까지 나갈거란다. 같이가자.`","characters":["P-6eeed2b4661f"]},{"id":"RP-II-0112288","time":"2026-06-30T15:10:00+09:00","room":"RP II","name":"아도니스","profile":"올리브","identity":"reviewed","type":"dialogue","body":"아버지는 아이들을 수레에 태우고 언덕과 강을 넘어 먼 숲에 데려갔어요. 그러더니 이럴수가. 아이들을 버리고 혼자만 도망을 갔지 뭐에요?","characters":["P-6eeed2b4661f"]},{"id":"RP-II-0112289","time":"2026-06-30T15:10:00+09:00","room":"RP II","name":"아도니스","profile":"올리브","identity":"reviewed","type":"dialogue","body":"헉.","characters":["P-6eeed2b4661f"]},{"id":"RP-II-0112290","time":"2026-06-30T15:10:00+09:00","room":"RP II","name":"아도니스","profile":"올리브","identity":"reviewed","type":"dialogue","body":"나쁜 사람이다.","characters":["P-6eeed2b4661f"]},{"id":"RP-II-0112291","time":"2026-06-30T15:11:00+09:00","room":"RP II","name":"아도니스","profile":"올리브","identity":"reviewed","type":"dialogue","body":"그치만 똑똑한 잭은 수레바퀴의 자국을 잡아냈어요. 여동생의 손을 꼭 잡고 집으로 걸어갔죠.","characters":["P-6eeed2b4661f"]},{"id":"RP-II-0112292","time":"2026-06-30T15:12:00+09:00","room":"RP II","name":"아도니스","profile":"올리브","identity":"reviewed","type":"dialogue","body":"그러나 강을 넘는 길목에서 비가 내려, 그만 또다시 길을 잃어버리고 말았어요.","characters":["P-6eeed2b4661f"]},{"id":"RP-II-0112293","time":"2026-06-30T15:14:00+09:00","room":"RP II","name":"아도니스","profile":"올리브","identity":"reviewed","type":"dialogue","body":"두 사람은 낯선 길을 헤메이고, 똑 헤메었답니다. 배에선 꼬르륵 소리가 나고, 발은 아파왔어요.","characters":["P-6eeed2b4661f"]},{"id":"RP-II-0112294","time":"2026-06-30T15:14:00+09:00","room":"RP II","name":"아도니스","profile":"올리브","identity":"reviewed","type":"dialogue","body":"그러다 찾았습니다.","characters":["P-6eeed2b4661f"]},{"id":"RP-II-0112295","time":"2026-06-30T17:11:00+09:00","room":"RP II","name":"어설픈 용 ⃢맹","profile":"어설픈 용 ⃢맹","identity":"unresolved","type":"dialogue","body":"무엇을요?","characters":[]},{"id":"RP-II-0112296","time":"2026-06-30T17:50:00+09:00","room":"RP II","name":"리키","profile":"리키","identity":"unresolved","type":"dialogue","body":"♧바로 응가를요","characters":[]},{"id":"RP-II-0112297","time":"2026-06-30T18:14:00+09:00","room":"RP II","name":"아도니스","profile":"올리브","identity":"reviewed","type":"dialogue","body":"헉.","characters":["P-6eeed2b4661f"]},{"id":"RP-II-0112298","time":"2026-06-30T18:15:00+09:00","room":"RP II","name":"아도니스","profile":"올리브","identity":"reviewed","type":"dialogue","body":"-fin","characters":["P-6eeed2b4661f"]},{"id":"RP-II-0112299","time":"2026-06-30T18:15:00+09:00","room":"RP II","name":"판정·진행 봇","profile":"《운명의 굴레》","identity":"bot","type":"bot","body":"-fin","characters":[]}]};
